action_priority_list_t* precombat = get_action_priority_list( "precombat" );
action_priority_list_t* def = get_action_priority_list( "default" );
action_priority_list_t* cat = get_action_priority_list( "cat" );
action_priority_list_t* healing = get_action_priority_list( "healing" );

precombat->add_action( "cat_form,if=talent.rake.enabled","Executed before combat begins. Accepts non-harmful actions only." );
precombat->add_action( "prowl,if=talent.rake.enabled" );

def->add_action( "berserking","Executed every time the actor is available." );
def->add_action( "run_action_list,name=healing,if=!buff.prowl.up&!buff.shadowmeld.up,line_cd=12" );
def->add_action( "use_items,if=!buff.prowl.up&!buff.shadowmeld.up" );
def->add_action( "potion,if=!buff.prowl.up&!buff.shadowmeld.up" );
def->add_action( "heart_of_the_wild,if=(buff.cat_form.up&!buff.prowl.up&!buff.shadowmeld.up&(talent.circle_of_the_wild.enabled|spell_targets.starfire=1))|(buff.moonkin_form.up&talent.circle_of_the_heavens.enabled&spell_targets.starfire>1)" );
def->add_action( "run_action_list,name=cat,if=talent.circle_of_the_wild.enabled" );
def->add_action( "cat_form,if=talent.circle_of_the_wild.enabled|(spell_targets.starfire=1&!buff.cat_form.up&cooldown.heart_of_the_wild.up)" );
def->add_action( "convoke_the_spirits,if=buff.moonkin_form.up" );
def->add_action( "sunfire,target_if=refreshable&target.time_to_die>5" );
def->add_action( "starsurge,if=active_enemies<8" );
def->add_action( "starfire,if=(talent.liveliness.enabled&(buff.call_of_the_elder_druid.up&spell_targets.starfire>3|spell_targets.starfire>5))|(talent.master_shapeshifter.enabled&(buff.call_of_the_elder_druid.up&spell_targets.starfire>1|spell_targets.starfire>2))|(buff.heart_of_the_wild.up&spell_targets.starfire>2|spell_targets.starfire>4)" );
def->add_action( "moonfire,target_if=refreshable&time_to_die>12" );
def->add_action( "starfire,if=spell_targets.starfire>1" );
def->add_action( "wrath" );

cat->add_action( "rake,if=buff.shadowmeld.up|buff.prowl.up" );
cat->add_action( "auto_attack,if=!buff.prowl.up&!buff.shadowmeld.up" );
cat->add_action( "starfire,if=buff.call_of_the_elder_druid.up&spell_targets.starfire>3|talent.master_shapeshifter.enabled&(spell_targets.starfire>5|buff.call_of_the_elder_druid.up&spell_targets.starfire>2)" );
cat->add_action( "thrash,target_if=refreshable|dot.thrash.stack<3&buff.bear_form.up" );
cat->add_action( "rake,target_if=refreshable&time_to_die>6&talent.fluid_form.enabled&!buff.cat_form.up" );
cat->add_action( "shred,target_if=time_to_die<6&talent.fluid_form.enabled&!buff.cat_form.up" );
cat->add_action( "cat_form,if=talent.convoke_the_spirits.enabled&(active_enemies<=6)&(!buff.cat_form.up&cooldown.convoke_the_spirits.remains<=gcd.max)" );
cat->add_action( "convoke_the_spirits,if=(buff.cat_form.up&combo_points<4)" );
cat->add_action( "rip,target_if=((refreshable|energy>90&remains<=10)&(combo_points=5&time_to_die>remains+24|(remains+combo_points*4<time_to_die&remains+4+combo_points*4>time_to_die))|!ticking&combo_points>2)" );
cat->add_action( "mangle,if=talent.fluid_form.enabled&(dot.thrash.remains<4|dot.thrash.stack<3|energy<30)&cooldown.mangle.up" );
cat->add_action( "pool_resource,for_next=1" );
cat->add_action( "sunfire,target_if=(refreshable&target.time_to_die>5)&!prev_gcd.1.cat_form" );
cat->add_action( "rake,target_if=refreshable&(time_to_die>8&!ticking)|(active_dot.rake<1&talent.primal_fury.enabled&talent.master_shapeshifter.enabled&spell_targets.swipe_cat>4)" );
cat->add_action( "cat_form,if=!buff.cat_form.up&energy>60&(cooldown.healing.remains>(gcd.max*2)|!druid.time_spend_healing)&!talent.fluid_form.enabled" );
cat->add_action( "moonfire,target_if=(refreshable&time_to_die>12&!ticking|(prev_gcd.1.sunfire&remains<duration*0.8&spell_targets.sunfire=1))&!prev_gcd.1.cat_form&spell_targets.swipe_cat<4" );
cat->add_action( "sunfire,if=prev_gcd.1.moonfire&remains<duration*0.8" );
cat->add_action( "cat_form,if=!buff.cat_form.up&energy>50&!talent.fluid_form.enabled" );
cat->add_action( "pool_resource,for_next=1" );
cat->add_action( "ferocious_bite,target_if=(combo_points>3&target.time_to_die<3)|(combo_points=5&energy>=50&dot.rip.remains>10)&spell_targets.swipe_cat<4" );
cat->add_action( "rake,target_if=refreshable&time_to_die>10&(!talent.primal_fury.enabled|!talent.master_shapeshifter.enabled|!spell_targets.swipe_cat>4)" );
cat->add_action( "swipe_cat,if=active_enemies>2&combo_points<5" );
cat->add_action( "pool_resource,for_next=1" );
cat->add_action( "shred,if=energy>60&combo_points<5" );
cat->add_action( "cat_form,if=!buff.cat_form.up" );

healing->add_action( "strict_sequence,name=heal:regrowth:regrowth:regrowth:regrowth" );
